// Assuming you have a setup with bpmn-js and diagram-js

// Import necessary modules
import BpmnModeler from 'bpmn-js/lib/Modeler';
import { is } from 'bpmn-js/lib/util/ModelUtil';

// Initialize the BPMN modeler
const modeler = new BpmnModeler({
  container: '#canvas'
});

// Function to replace DataObjectReference with DataStoreReference
function replaceElement(element) {
  const modeling = modeler.get('modeling');
  const elementRegistry = modeler.get('elementRegistry');

  // Find the element to replace
  const dataObjectReference = elementRegistry.get(element.id);

  if (is(dataObjectReference, 'bpmn:DataObjectReference')) {
    // Replace with DataStoreReference
    modeling.replaceShape(dataObjectReference, {
      type: 'bpmn:DataStoreReference'
    });
  } else if (is(dataObjectReference, 'bpmn:DataStoreReference')) {
    // Replace with DataObjectReference
    modeling.replaceShape(dataObjectReference, {
      type: 'bpmn:DataObjectReference'
    });
  }
}

// Example usage
const element = { id: 'DataObjectReference_1' }; // Replace with actual element ID
replaceElement(element);
